"use strict";const e=require("../common/vendor.js"),i=require("../api/index.js"),t=require("./location-format.js");exports.getCurrentAddress=async function(){const r=await new Promise((i,t)=>{e.index.getLocation({type:"wgs84",isHighAccuracy:!0,success:e=>{i({latitude:e.latitude,longitude:e.longitude})},fail:e=>{var i;t(new Error((i=(null==e?void 0:e.errMsg)||"定位失败").includes("auth")||i.includes("authorize")||i.includes("denied")||i.includes("permission")?"定位权限未开启，请允许获取位置后重试":i.includes("timeout")?"定位超时，请检查网络或 GPS 后重试":"定位失败，请允许获取位置或手动选择城市/省份"))}})}),n=await i.reverseLocation(r.latitude,r.longitude);if(200!==n.code||!n.data)throw new Error(n.msg||"当前位置解析失败");return{...n.data,label:t.formatLocationLabel(n.data)}};
